# hermes-device-sync: `hermes` with no arguments = sync, resume the newest conversation from ANY of
# your devices (with its recap), and sync again when you exit. With arguments it is plain Hermes.
# `hermes-new` = plain Hermes. `Sync-Hermes` = sync now. Generated by setup.py; re-run setup to change.
$HermesSyncScripts = '__SCRIPTS__'
$HermesSyncPython = '__PYTHON__'
function Sync-Hermes { & $HermesSyncPython (Join-Path $HermesSyncScripts 'sync.py') }
function hermes {
    $exe = (Get-Command hermes -CommandType Application | Select-Object -First 1).Source
    if ($args.Count -gt 0) { & $exe @args; return }
    $h = Join-Path $HermesSyncScripts 'handoff.py'
    Sync-Hermes
    $id = (& $HermesSyncPython $h pick 2>$null | Select-Object -Last 1)
    & $HermesSyncPython $h prepare $id 2>$null
    if ($id) { & $exe --resume $id } else { & $exe -c }
    Write-Host 'Saving the conversation (recap + sync)...' -ForegroundColor DarkGray
    & $HermesSyncPython $h summarize 2>$null
    Sync-Hermes
}
function hermes-new {
    $exe = (Get-Command hermes -CommandType Application | Select-Object -First 1).Source
    & $exe @args
}
